namespace CapybaraGame.Puzzle{public sealed class DeterministicRandom{uint state;public DeterministicRandom(int seed){state=unchecked((uint)seed);if(state==0)state=0x6D2B79F5u;}public uint NextUInt(){uint z=state+=0x9E3779B9u;z=(z^(z>>16))*0x21F0AAADu;z=(z^(z>>15))*0x735A2D97u;return z^(z>>15);}public int NextInt(int min,int max){return max<=min?min:min+(int)(NextUInt()%(uint)(max-min));}public double NextDouble()=>NextUInt()/4294967296.0;}}